import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"Agents / ACP","description":"","frontmatter":{},"headers":[],"relativePath":"guides/acp.md","filePath":"guides/acp.md","lastUpdated":1790952322000}'),n={name:"guides/acp.md"};function r(i,e,d,l,h,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="agents-acp" tabindex="-1">Agents / ACP <a class="header-anchor" href="#agents-acp" aria-label="Permalink to &quot;Agents / ACP&quot;">​</a></h1><p>Memoh can connect a bot to ACP-compatible coding agents. ACP agents are external coding workflows that work from the bot&#39;s chat workspace while keeping their sessions separate from normal chat and discuss conversations.</p><p>Two agent profiles ship with Memoh: <strong>Codex</strong> and <strong>Claude Code</strong>. Treat them as supported setup paths, not as the only possible ACP-compatible agents over time.</p><p>ACP agents run inside the bot&#39;s container workspace, so the bot must use a container-backed workspace backend.</p><hr><h2 id="setup-flow" tabindex="-1">Setup Flow <a class="header-anchor" href="#setup-flow" aria-label="Permalink to &quot;Setup Flow&quot;">​</a></h2><ol><li>Open a bot&#39;s <strong>Detail Page</strong> and go to the <strong>Agents</strong> tab.</li><li>Each agent appears as a row with an enable switch. Click the row to open its settings.</li><li>Choose a setup mode and fill in the fields that agent requires.</li><li>Save, then start the enabled agent from the chat workspace.</li></ol><p>A row shows one of three states: <strong>Needs setup</strong> (enabled but missing credentials), <strong>Disabled</strong>, or a green dot (enabled and ready).</p><h3 id="setup-modes-per-agent" tabindex="-1">Setup Modes Per Agent <a class="header-anchor" href="#setup-modes-per-agent" aria-label="Permalink to &quot;Setup Modes Per Agent&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>API Key</th><th>OAuth</th><th>Self-managed</th></tr></thead><tbody><tr><td><strong>Codex</strong></td><td>✅</td><td>✅ ChatGPT sign-in with device code</td><td>✅</td></tr><tr><td><strong>Claude Code</strong></td><td>✅</td><td>✅ paste a token from <code>claude setup-token</code></td><td>✅</td></tr></tbody></table><p><strong>Self-managed</strong> means Memoh launches the agent against configuration you maintain yourself inside the workspace.</p><h3 id="codex-device-authorization" tabindex="-1">Codex Device Authorization <a class="header-anchor" href="#codex-device-authorization" aria-label="Permalink to &quot;Codex Device Authorization&quot;">​</a></h3><p>In the Codex settings, click <strong>Use Device Code</strong>. Memoh shows a verification URL and a one-time user code, and finishes authorization automatically once you approve it on OpenAI&#39;s page.</p><blockquote><p>Only enter the code on the displayed OpenAI verification URL — device codes can be used for phishing.</p></blockquote><h2 id="adapter-updates" tabindex="-1">Adapter Updates <a class="header-anchor" href="#adapter-updates" aria-label="Permalink to &quot;Adapter Updates&quot;">​</a></h2><p>The Codex and Claude Code adapters are npm-backed. Memoh resolves the adapter&#39;s latest published version once per server run (per bot) and launches that version, so adapter fixes arrive without upgrading Memoh itself. If the lookup or launch fails, Memoh falls back to the adapter version bundled in the workspace image until the next server restart.</p><hr><h2 id="reasoning-effort" tabindex="-1">Reasoning Effort <a class="header-anchor" href="#reasoning-effort" aria-label="Permalink to &quot;Reasoning Effort&quot;">​</a></h2><p>When the active agent supports it, you can pick a reasoning effort per session from the model picker in the composer: hover <strong>Reasoning</strong> to open the list.</p><ul><li>The available options (and their names) are declared by the external agent itself; they can change when you switch models.</li><li>Defaults when you have not chosen one: Codex uses <code>medium</code>, Claude Code uses <code>high</code>.</li><li>The choice is per session and independent of the model choice.</li></ul><p>If a previously chosen effort becomes unavailable, Memoh refreshes the agent&#39;s options and asks you to pick again instead of failing silently.</p><hr><h2 id="attachments" tabindex="-1">Attachments <a class="header-anchor" href="#attachments" aria-label="Permalink to &quot;Attachments&quot;">​</a></h2><p>ACP agent sessions support message attachments:</p><ul><li><strong>Images</strong> are sent natively when the agent declares image input support. Otherwise, Memoh automatically falls back to referencing the image as a workspace file when possible.</li><li><strong>Files</strong>, long pasted text, and attachments carried by quoted/replied messages are passed to the agent as workspace paths or public URLs.</li><li>Sending an attachment without any text is allowed.</li></ul><p>If an attachment cannot be delivered to the agent, Memoh reports a clear error in chat instead of silently dropping it.</p><hr><h2 id="default-agent" tabindex="-1">Default Agent <a class="header-anchor" href="#default-agent" aria-label="Permalink to &quot;Default Agent&quot;">​</a></h2><p>In the bot&#39;s interaction settings you can pick a <strong>Default Agent</strong> — Memoh itself or any enabled, fully configured ACP agent. The default applies to newly created one-on-one sessions only; existing sessions and group discuss conversations are not affected.</p><hr><h2 id="acp-agent-sessions" tabindex="-1">ACP Agent Sessions <a class="header-anchor" href="#acp-agent-sessions" aria-label="Permalink to &quot;ACP Agent Sessions&quot;">​</a></h2><p>ACP work uses the <code>acp_agent</code> session type. These sessions are created and managed by the Agents/ACP workflow, not through normal <code>/new chat</code> or <code>/new discuss</code> routing. In the app, you can filter sessions by <code>acp_agent</code> to find coding-agent work separately from everyday conversations.</p><hr><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./working-with-bots.html">Bot Management</a></li><li><a href="./sessions.html">Sessions</a></li><li><a href="./files.html">Files</a></li><li><a href="./../integrations/providers/llm.html">Providers And Models</a></li></ul>',35)])])}const u=t(n,[["render",r]]);export{g as __pageData,u as default};
